	@Test
	void rootMorselsSatisfyReplayPagesOnTheirOwnBoundaries() throws Exception {
		try (Fixture fixture = new Fixture(5)) {
			fixture.set(LmdbNativePackedMorsels.ROWS_PROPERTY, "2");
			LmdbNativeCostQuote quote = parallelQuote(fixture, fixture.join, new int[] { 0, 1 }, false);
			assertThat(quote.chunked()).isNotNull();
			assertThat(quote.chunked().batchSize()).isEqualTo(4);
			double unit = quote.total().expected(Feature.GENERATED_ROW) / 16D;
			double roots = quote.chunked().rawRootWork().expected(Feature.BATCH_ROW)
					+ quote.chunked().descendantWork().expected(Feature.BATCH_ROW);
			double[] demands = { 0D, 1D, 5D, 6D, 16D };
			double[] replayRows = { 0D, 5D, 5D, 10D, 16D };
			double[] rootRows = { 0D, 8D, 8D, 12D, 16D };
			for (int index = 0; index < demands.length; index++) {
				LmdbNativeCostVector features = quote.forSlice(demands[index]);
				assertThat(features.expected(Feature.BATCH_ROW)).as("root construction at demand %s", demands[index])
						.isCloseTo(roots * rootRows[index] / 16D, within(1e-10));
				assertThat(features.expected(Feature.GENERATED_ROW)).as("replay at demand %s", demands[index])
						.isCloseTo(unit * replayRows[index], within(1e-10));
				assertThat(features.expected(Feature.OUTPUT_MATERIALIZATION)).isEqualTo(demands[index]);
				if (demands[index] > 0D) {
					assertThat(features.high(Feature.GENERATED_ROW))
							.isEqualTo(quote.total().high(Feature.GENERATED_ROW));
				}
			}
			assertThat(quote.withOutputRows(Double.NaN).forSlice(1D).expected(Feature.GENERATED_ROW))
					.isEqualTo(16D * unit);
		}
	}

